import * as React from "react";
import {
  Page,
  BlockStack,
  InlineStack,
  Grid,
  Banner,
  ButtonGroup,
  Button,
  Text,
} from "@xco-agency/corex-ui";
import {
  ALL_PRICING_PLANS,
  CURRENT_USAGE_LIMITS,
  FREE_PLAN,
  PRICING_FAQS,
  PRICING_PLANS,
} from "../constants";
import { ActivePlanCard } from "../partials/ActivePlanCard";
import { PricingCard } from "../partials/PricingCard";
import { PricingFaq } from "../partials/PricingFaq";
import { PricingIntervalToggle } from "../partials/PricingIntervalToggle";
import { PricingUpgradeModal } from "../partials/PricingUpgradeModal";
import { PricingUsageMeter } from "../partials/PricingUsageMeter";
import type {
  ActivePlanCardVariantType,
  BillingIntervalType,
  PlanTierIdType,
  PricingPlanType,
  PricingPlansExamplePropsType,
} from "../types";

export function PricingPlansExample({
  initialPlanId = "free",
  initialInterval = "monthly",
}: PricingPlansExamplePropsType) {
  const [currentPlanId, setCurrentPlanId] =
    React.useState<PlanTierIdType>(initialPlanId);
  const [interval, setInterval] =
    React.useState<BillingIntervalType>(initialInterval);
  const [variant, setVariant] =
    React.useState<ActivePlanCardVariantType>("banner");
  const [selectedPlanForUpgrade, setSelectedPlanForUpgrade] =
    React.useState<PricingPlanType | null>(null);
  const [isProcessing, setIsProcessing] = React.useState(false);
  const [successBanner, setSuccessBanner] = React.useState<string | null>(null);

  const currentPlan: PricingPlanType =
    ALL_PRICING_PLANS.find((p) => p.id === currentPlanId) ?? FREE_PLAN;

  const handleSelectPlan = (plan: PricingPlanType) => {
    setSelectedPlanForUpgrade(plan);
  };

  const handleChangePlanClick = () => {
    // Open upgrade modal with Growth or next tier
    const nextPlan =
      PRICING_PLANS.find((p) => p.id !== currentPlanId) ?? PRICING_PLANS[1]!;
    setSelectedPlanForUpgrade(nextPlan);
  };

  const handleConfirmUpgrade = () => {
    if (!selectedPlanForUpgrade) return;
    setIsProcessing(true);

    setTimeout(() => {
      setCurrentPlanId(selectedPlanForUpgrade.id);
      setIsProcessing(false);
      setSuccessBanner(
        `Successfully subscribed to the ${selectedPlanForUpgrade.name} plan!`,
      );
      setSelectedPlanForUpgrade(null);
    }, 600);
  };

  return (
    <Page
      heading="Plans & Billing"
      subheading="Manage your active subscription, compare tiers, and unlock advanced revenue engines."
      inlineSize="large"
    >
      <BlockStack gap="base">
        {successBanner && (
          <Banner
            tone="success"
            title={successBanner}
            onDismiss={() => setSuccessBanner(null)}
          />
        )}

        {/* Active Plan Component with Plan Avatar SVG */}
        <ActivePlanCard
          plan={currentPlan}
          interval={interval}
          variant={variant}
          nextBillingDate="Oct 01, 2026"
          onChangePlan={handleChangePlanClick}
          onManageBilling={() =>
            setSuccessBanner("Opening Shopify billing portal...")
          }
        />

        {/* Interactive Controls Bar: Quick Avatar Switcher & Card/Banner Style Toggle */}
        <InlineStack justifyContent="space-between" alignItems="center" gap="base" wrap>
          <InlineStack gap="small-200" alignItems="center">
            <Text variant="small" tone="neutral">
              Simulate Active Tier:
            </Text>
            <InlineStack gap="small-100" alignItems="center">
              <Button
                variant={currentPlanId === "free" ? "primary" : "secondary"}
                onClick={() => setCurrentPlanId("free")}
              >
                Free (Gem)
              </Button>
              <Button
                variant={currentPlanId === "starter" ? "primary" : "secondary"}
                onClick={() => setCurrentPlanId("starter")}
              >
                Starter (Rocket)
              </Button>
              <Button
                variant={currentPlanId === "growth" ? "primary" : "secondary"}
                onClick={() => setCurrentPlanId("growth")}
              >
                Growth (Surge)
              </Button>
              <Button
                variant={currentPlanId === "scale" ? "primary" : "secondary"}
                onClick={() => setCurrentPlanId("scale")}
              >
                Scale (Crown)
              </Button>
            </InlineStack>
          </InlineStack>

          <InlineStack gap="small-200" alignItems="center">
            <Text variant="small" tone="neutral">
              Component Style:
            </Text>
            <InlineStack gap="small-100" alignItems="center">
              <Button
                variant={variant === "banner" ? "primary" : "secondary"}
                onClick={() => setVariant("banner")}
              >
                Banner Style
              </Button>
              <Button
                variant={variant === "card" ? "primary" : "secondary"}
                onClick={() => setVariant("card")}
              >
                Card Style
              </Button>
            </InlineStack>
          </InlineStack>
        </InlineStack>

        {/* Billing Interval Toggle */}
        <PricingIntervalToggle
          interval={interval}
          discountPercentage={20}
          onChange={setInterval}
        />

        {/* 3-Tier Pricing Cards Grid */}
        <Grid columns={{ xs: 1, sm: 1, md: 3, lg: 3 }} gap="base">
          {PRICING_PLANS.map((plan) => (
            <PricingCard
              key={plan.id}
              plan={plan}
              interval={interval}
              isCurrent={plan.id === currentPlanId}
              onSelectPlan={handleSelectPlan}
            />
          ))}
        </Grid>

        {/* Current Billing Usage Meter */}
        <PricingUsageMeter limits={CURRENT_USAGE_LIMITS} />

        {/* FAQ Accordion */}
        <PricingFaq items={PRICING_FAQS} />

        {/* Upgrade / Confirmation Modal */}
        <PricingUpgradeModal
          open={selectedPlanForUpgrade !== null}
          selectedPlan={selectedPlanForUpgrade}
          interval={interval}
          isProcessing={isProcessing}
          onClose={() => setSelectedPlanForUpgrade(null)}
          onConfirm={handleConfirmUpgrade}
        />
      </BlockStack>
    </Page>
  );
}

export * from "./types";
export * from "./constants";
export { ActivePlanCard } from "./partials/ActivePlanCard";
export { PlanAvatar } from "./partials/PlanAvatar";
export { PricingIntervalToggle } from "./partials/PricingIntervalToggle";
export { PricingCard } from "./partials/PricingCard";
export { PricingUsageMeter } from "./partials/PricingUsageMeter";
export { PricingFaq } from "./partials/PricingFaq";
export { PricingUpgradeModal } from "./partials/PricingUpgradeModal";
export { PricingPlansExample } from "./examples/PricingPlansExample";

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Divider,
  IconTile,
  Icon,
} from "@xco-agency/corex-ui";
import type { PricingCardPropsType } from "../types";

export function PricingCard({
  plan,
  interval,
  isCurrent,
  onSelectPlan,
}: PricingCardPropsType) {
  const price = interval === "annual" ? plan.annualPrice : plan.monthlyPrice;
  const annualTotal = plan.annualPrice * 12;

  return (
    <Card>
      <BlockStack gap="base">
        {/* Header with Title & Badges */}
        <InlineStack alignItems="center" justifyContent="space-between" gap="small-200">
          <Text variant="large" heading>
            {plan.name}
          </Text>

          {isCurrent ? (
            <Badge tone="info">Current plan</Badge>
          ) : plan.badge ? (
            <Badge tone="success">{plan.badge}</Badge>
          ) : null}
        </InlineStack>

        <Text variant="small" tone="neutral">
          {plan.description}
        </Text>

        {/* Price Display */}
        <BlockStack gap="none">
          <InlineStack alignItems="baseline" gap="small-100">
            <span
              style={{
                fontSize: "32px",
                fontWeight: 700,
                color: "var(--p-color-text)",
                lineHeight: 1.1,
              }}
            >
              ${price}
            </span>
            <Text as="span" variant="small" tone="neutral">
              / month
            </Text>
          </InlineStack>

          {interval === "annual" && (
            <Text variant="xs" tone="neutral">
              ${annualTotal} billed once per year
            </Text>
          )}
        </BlockStack>

        {/* CTA Button */}
        {isCurrent ? (
          <Button variant="secondary" disabled>
            Current active plan
          </Button>
        ) : (
          <Button
            variant={plan.isPopular ? "primary" : "secondary"}
            onClick={() => onSelectPlan(plan)}
          >
            {`Select ${plan.name}`}
          </Button>
        )}

        <Divider />

        {/* Features Checklist */}
        <BlockStack gap="small-200">
          <Text variant="xs" tone="neutral">
            INCLUDED WITH {plan.name.toUpperCase()}:
          </Text>

          {plan.features.map((feature, idx) => (
            <InlineStack key={idx} gap="small-200" alignItems="start">
              <Icon type={feature.included ? "check" : "minus"} size="small" />

              <Text as="span" type={feature.included ? "generic" : "redundant"}>
                {feature.title}
              </Text>
            </InlineStack>
          ))}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Collapsible,
  Divider,
  Icon,
  Box,
} from "@xco-agency/corex-ui";
import type { PricingFaqPropsType } from "../types";
import { Clickable } from "@xco-agency/corex-ui";

export function PricingFaq({ items }: PricingFaqPropsType) {
  return (
    <Card padding="none">
      <BlockStack>
        <BlockStack gap="none" padding="base">
          <Text variant="base" heading>
            Frequently asked questions
          </Text>
          <Text variant="small" color="subdued">
            Everything you need to know about billing, trials, and plan limits.
          </Text>
        </BlockStack>

        <BlockStack>
          {items.map((item, idx) => (
            <React.Fragment key={item.id}>
              {idx > 0 && <Divider />}

              <Collapsible
                content={
                  <Box paddingInline="base" paddingBlock="small-300">
                    <Text variant="small" tone="neutral">
                      {item.answer}
                    </Text>
                  </Box>
                }
              >
                {({ expanded, toggle }) => (
                  <Clickable
                    onClick={toggle}

                    paddingInline="base"
                    paddingBlock="small-200"
                    inlineSize="fill"
                  >
                    <InlineStack justifyContent="space-between" alignItems="center">
                      <Text variant="small" heading>
                        {item.question}
                      </Text>

                      <Icon type={expanded ? "chevron-up" : "chevron-down"} />
                    </InlineStack>
                  </Clickable>
                )}
              </Collapsible>
            </React.Fragment>
          ))}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  InlineStack,
  ButtonGroup,
  Button,
  Badge,
  Text,
} from "@xco-agency/corex-ui";
import type { PricingIntervalTogglePropsType } from "../types";

export function PricingIntervalToggle({
  interval,
  discountPercentage = 20,
  onChange,
}: PricingIntervalTogglePropsType) {
  return (
    <InlineStack gap="base" alignItems="center" justifyContent="center">
      <ButtonGroup>
        <Button
          variant={interval === "monthly" ? "primary" : "secondary"}
          onClick={() => onChange("monthly")}
        >
          Monthly billing
        </Button>
        <Button
          variant={interval === "annual" ? "primary" : "secondary"}
          onClick={() => onChange("annual")}
        >
          Annual billing
        </Button>
      </ButtonGroup>

      <InlineStack gap="small-200" alignItems="center">
        <Badge tone="success">{`Save ${discountPercentage}%`}</Badge>
        <Text as="span" variant="xs" tone="neutral">
          Billed annually
        </Text>
      </InlineStack>
    </InlineStack>
  );
}

import * as React from "react";
import { Modal, BlockStack, InlineStack, Text, Badge } from "@xco-agency/corex-ui";
import type { PricingUpgradeModalPropsType } from "../types";

export function PricingUpgradeModal({
  open,
  selectedPlan,
  interval,
  isProcessing,
  onClose,
  onConfirm,
}: PricingUpgradeModalPropsType) {
  if (!selectedPlan) return null;

  const price =
    interval === "annual"
      ? selectedPlan.annualPrice
      : selectedPlan.monthlyPrice;

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={`Confirm subscription: ${selectedPlan.name}`}
      primaryAction={{
        content: isProcessing
          ? "Approving with Shopify..."
          : `Approve $${price}/mo on Shopify`,
        onAction: onConfirm,
        loading: isProcessing,
      }}
      secondaryActions={[
        {
          content: "Cancel",
          onAction: onClose,
          disabled: isProcessing,
        },
      ]}
    >
      <BlockStack gap="base">
        <InlineStack
          justifyContent="space-between"
          alignItems="center"
          gap="small-200"
        >
          <BlockStack gap="none">
            <Text variant="base" heading>
              {selectedPlan.name} Plan
            </Text>
            <Text variant="small" tone="neutral">
              {interval === "annual" ? "Annual billing cycle" : "Monthly billing cycle"}
            </Text>
          </BlockStack>

          <InlineStack gap="small-100" alignItems="baseline">
            <span
              style={{
                fontSize: "24px",
                fontWeight: 700,
                color: "var(--p-color-text)",
              }}
            >
              ${price}
            </span>
            <Text as="span" variant="xs" tone="neutral">
              / mo
            </Text>
          </InlineStack>
        </InlineStack>

        <div
          style={{
            background: "var(--p-color-bg-surface-secondary)",
            padding: "12px 16px",
            borderRadius: "var(--p-border-radius-100)",
            border: "1px solid var(--p-color-border-subdued)",
          }}
        >
          <BlockStack gap="small-100">
            <InlineStack gap="small-200" alignItems="center">
              <Badge tone="info">Shopify App Billing</Badge>
              <Text variant="xs" tone="neutral">
                Direct invoicing
              </Text>
            </InlineStack>
            <Text variant="small" tone="neutral">
              By confirming, Shopify will prorate your current billing period and
              apply the new plan limits immediately to your storefront.
            </Text>
          </BlockStack>
        </div>
      </BlockStack>
    </Modal>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  ProgressBar,
} from "@xco-agency/corex-ui";
import type { PricingUsageMeterPropsType } from "../types";

export function PricingUsageMeter({ limits }: PricingUsageMeterPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <BlockStack gap="none">
          <Text variant="base" heading>
            Current billing cycle usage
          </Text>
          <Text variant="small" tone="neutral">
            Track resource consumption against your current plan limits.
          </Text>
        </BlockStack>

        <BlockStack gap="base">
          {limits.map((item, idx) => {
            const percent = Math.min(
              100,
              Math.round((item.used / item.limit) * 100),
            );
            const isHighUsage = percent >= 80;

            return (
              <BlockStack key={idx} gap="small-200">
                <InlineStack
                  justifyContent="space-between"
                  alignItems="center"
                >
                  <Text variant="small" heading>
                    {item.label}
                  </Text>
                  <Text variant="small" tone={isHighUsage ? "warning" : "neutral"}>
                    {item.used.toLocaleString()} / {item.limit.toLocaleString()}{" "}
                    {item.unit} ({percent}%)
                  </Text>
                </InlineStack>

                <ProgressBar
                  progress={percent}
                  size="sm"
                  borderRadius="full"
                  tone={isHighUsage ? "caution" : "success"}
                />
              </BlockStack>
            );
          })}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import type * as React from "react";

export type BillingIntervalType = "monthly" | "annual";

export type PlanTierIdType = "free" | "starter" | "growth" | "scale" | "enterprise";

export type PlanFeatureType = {
  title: string;
  included: boolean;
  tooltip?: string;
};

export type PricingPlanType = {
  id: PlanTierIdType;
  name: string;
  monthlyPrice: number;
  annualPrice: number;
  description: string;
  badge?: string;
  isPopular?: boolean;
  features: PlanFeatureType[];
};

export type PlanUsageLimitType = {
  label: string;
  used: number;
  limit: number;
  unit: string;
};

export type FaqItemType = {
  id: string;
  question: string;
  answer: string;
};

export type PlanAvatarPropsType = {
  planId: PlanTierIdType | string;
  size?: number;
  customSvg?: React.ReactNode;
};

export type ActivePlanCardVariantType = "banner" | "card";

export type ActivePlanCardPropsType = {
  plan: PricingPlanType;
  interval?: BillingIntervalType;
  statusText?: string;
  statusTone?: "info" | "success" | "warning" | "neutral";
  billingNote?: string;
  nextBillingDate?: string;
  variant?: ActivePlanCardVariantType;
  onChangePlan?: () => void;
  onManageBilling?: () => void;
};

export type PricingIntervalTogglePropsType = {
  interval: BillingIntervalType;
  discountPercentage?: number;
  onChange: (interval: BillingIntervalType) => void;
};

export type PricingCardPropsType = {
  plan: PricingPlanType;
  interval: BillingIntervalType;
  isCurrent: boolean;
  onSelectPlan: (plan: PricingPlanType) => void;
};

export type PricingUsageMeterPropsType = {
  limits: PlanUsageLimitType[];
};

export type PricingFaqPropsType = {
  items: FaqItemType[];
};

export type PricingUpgradeModalPropsType = {
  open: boolean;
  selectedPlan: PricingPlanType | null;
  interval: BillingIntervalType;
  isProcessing: boolean;
  onClose: () => void;
  onConfirm: () => void;
};

export type PricingPlansExamplePropsType = {
  initialPlanId?: PlanTierIdType;
  initialInterval?: BillingIntervalType;
};
